from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return parity(x) (0 or 1) for each x in xs, in input order.

    The work is done in parallel on a thread pool, but the result order
    always matches the input order, regardless of the worker count.
    """
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([0, 1, 2, 3, 4, 5]) == [0, 1, 0, 1, 0, 1]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_single() -> None:
    assert parities([7]) == [1]
    assert parities([8]) == [0]


def test_parities_negative() -> None:
    assert parities([-1, -2, -3, -4]) == [1, 0, 1, 0]


def test_parities_large_ints() -> None:
    big = 10**30
    assert parities([big, big + 1, -big - 1]) == [0, 1, 1]


def test_parities_preserves_order() -> None:
    xs = [i * i + 3 * i for i in range(1000)]
    assert parities(xs) == [parity(x) for x in xs]


def test_parities_order_not_dependent_on_run() -> None:
    xs = list(range(-500, 500))
    expected = [parity(x) for x in xs]
    for _ in range(5):
        assert parities(xs) == expected


def test_parities_does_not_mutate_input() -> None:
    xs = [5, 4, 3, 2, 1]
    copy = list(xs)
    result = parities(xs)
    assert xs == copy
    assert result == [1, 0, 1, 0, 1]
    assert result is not xs


@pytest.mark.parametrize("n", [1, 2, 3, 10, 257])
def test_parities_lengths(n: int) -> None:
    xs = list(range(n))
    out = parities(xs)
    assert len(out) == n
    assert all(p in (0, 1) for p in out)
    assert out == [i % 2 for i in xs]

